import sys, os, re
sys.stdout.reconfigure(encoding='utf-8')
root = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(root)
sys.path.insert(0, os.path.join(root, 'test'))
import gen_iso_v12 as G
P = 'index.html'
s = open(P, encoding='utf-8').read()

def rep(old, new):
    global s
    assert s.count(old) == 1, ('miss', s.count(old), old[:80]); s = s.replace(old, new)
def between(a, b, new, keep_a=False):
    """a 부터 b 바로 앞까지를 new 로(a, b 는 한 번만 나와야 함)"""
    global s
    assert s.count(a) == 1, ('a', s.count(a), a[:60]); i = s.index(a); j = s.index(b, i)
    s = s[:i] + (a if keep_a else '') + new + s[j:]
def swap_svg(viewbox, new_svg):
    global s
    pat = re.compile(r'<svg viewBox="%s"[^>]*>.*?</svg>' % re.escape(viewbox), re.S)
    m = pat.findall(s); assert len(m) == 1, (viewbox, len(m)); s = pat.sub(lambda _: new_svg, s, count=1)

swap_svg('0 0 1260 750', G.cutaway()); swap_svg('0 0 1622 400', G.sequence()); swap_svg('0 0 1250 980', G.exploded()); swap_svg('0 0 1200 520', G.heating())

